3	import { useState } from "react";
4	import { z } from "zod";
5	import styles from "./contact-form-section.module.css";
6	
7	/* ── Schema ─────────────────────────────────────────────────── */
8	const ContactSchema = z.object({
9	  firstName: z.string().min(1, "First name is required"),
10	  lastName: z.string().min(1, "Last name is required"),
11	  email: z.string().min(1, "Email is required").email("Enter a valid email"),
12	  phone: z.string().optional(),
13	  inquiryType: z.string().min(1, "Please select an option"),
14	  message: z.string().optional(),
15	});
16	
17	type ContactFields = z.infer<typeof ContactSchema>;
18	type FieldErrors = Partial<Record<keyof ContactFields, string>>;
19	type FormStatus = "idle" | "submitting" | "success" | "error";
20	
21	const INITIAL: ContactFields = {
22	  firstName: "",
23	  lastName: "",
24	  email: "",
25	  phone: "",
26	  inquiryType: "",
27	  message: "",
28	};
29	
30	const INQUIRY_OPTIONS = [
31	  { value: "new-project", label: "Start a New Project" },
32	  { value: "agency-partnership", label: "Agency Partnership" },
33	  { value: "technical-account-support", label: "Technical or Account Support" },
34	  { value: "team", label: "Join Our Team" },
35	  { value: "general-inquiry", label: "General Inquiry" },
36	];
37	
38	/* ── Component ──────────────────────────────────────────────── */
39	export function ContactFormSection() {
40	  const [fields, setFields] = useState<ContactFields>(INITIAL);
41	  const [errors, setErrors] = useState<FieldErrors>({});
42	  const [status, setStatus] = useState<FormStatus>("idle");
43	
44	  function validateField(name: keyof ContactFields, value: string) {
45	    const result = ContactSchema.safeParse({ ...fields, [name]: value });
46	    if (!result.success) {
47	      const fieldError = result.error.flatten().fieldErrors[name];
48	      setErrors((prev) => ({
49	        ...prev,
50	        [name]: fieldError?.[0] ?? undefined,
51	      }));
52	    } else {
53	      setErrors((prev) => ({ ...prev, [name]: undefined }));
54	    }
55	  }
56	
57	  function handleChange(
58	    e: React.ChangeEvent<
59	      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
60	    >
61	  ) {
62	    const { name, value } = e.target;
63	    setFields((prev) => ({ ...prev, [name]: value }));
64	  }
65	
66	  function handleBlur(
67	    e: React.FocusEvent<
68	      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
69	    >
70	  ) {
71	    const { name, value } = e.target;
72	    validateField(name as keyof ContactFields, value);
73	  }
74	
75	  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
76	    e.preventDefault();
77	    if (status === "submitting") return;
78	
79	    const result = ContactSchema.safeParse(fields);
80	    if (!result.success) {
81	      const fieldErrors = result.error.flatten().fieldErrors;
82	      const mapped: FieldErrors = {};
83	      for (const [k, v] of Object.entries(fieldErrors)) {
84	        const key = k as keyof ContactFields;
85	        if (v?.[0]) mapped[key] = v[0];
86	      }
87	      setErrors(mapped);
88	      return;
89	    }
90	
91	    setStatus("submitting");
92	    try {
93	      const res = await fetch("/api/contact", {
94	        method: "POST",
95	        headers: { "content-type": "application/json" },
96	        body: JSON.stringify(result.data),
97	      });
98	      if (!res.ok) throw new Error(`Request failed: ${res.status}`);
99	      setStatus("success");
100	      setFields(INITIAL);
101	      setErrors({});
102	    } catch {
103	      setStatus("error");
104	    }
105	  }
106	
107	  return (
108	    <section className={styles.section} aria-label="Contact form">
109	      <div className={styles.container}>
110	        {/* aria-live region for screen readers */}
111	        <div
112	          role="status"
113	          aria-live="polite"
114	          aria-atomic="true"
115	          className={styles.srOnly}
116	        >
117	          {status === "success"
118	            ? "Your message has been sent successfully."
119	            : status === "error"
120	            ? "Something went wrong. Please try again."
121	            : ""}
122	        </div>
123	
124	        {status === "success" ? (
125	          <div className={styles.successMsg}>
126	            Thank you! Your submission has been received!
127	            <br />
128	            Our team will get back to you within 12-24hrs.
129	          </div>
130	        ) : (
131	          <>
132	            <h3 className={styles.heading}>Send us a message.</h3>
133	
134	            <form
135	              onSubmit={handleSubmit}
136	              className={styles.form}
137	              noValidate
138	              aria-label="Send a message"
139	            >
140	              {/* First Name + Last Name */}
141	              <div className={styles.rowTwo}>
142	                <div className={styles.field}>
143	                  <div className={styles.labelRow}>
144	                    <label htmlFor="firstName" className={styles.label}>
145	                      First Name
146	                    </label>
147	                    <span className={styles.required} aria-hidden="true">
148	                      *
149	                    </span>
150	                  </div>
151	                  <input
152	                    id="firstName"
153	                    name="firstName"
154	                    type="text"
155	                    placeholder="John"
156	                    maxLength={256}
157	                    value={fields.firstName}
158	                    onChange={handleChange}
159	                    onBlur={handleBlur}
160	                    required
161	                    aria-required="true"
162	                    aria-invalid={!!errors.firstName}
163	                    aria-describedby={
164	                      errors.firstName ? "firstName-error" : undefined
165	                    }
166	                    className={styles.input}
167	                  />
168	                  {errors.firstName && (
169	                    <p
170	                      id="firstName-error"
171	                      className={styles.fieldError}
172	                      role="alert"
173	                    >
174	                      {errors.firstName}
175	                    </p>
176	                  )}
177	                </div>
178	
179	                <div className={styles.field}>
180	                  <div className={styles.labelRow}>
181	                    <label htmlFor="lastName" className={styles.label}>
182	                      Last Name
183	                    </label>
184	                    <span className={styles.required} aria-hidden="true">
185	                      *
186	                    </span>
187	                  </div>
188	                  <input
189	                    id="lastName"
190	                    name="lastName"
191	                    type="text"
192	                    placeholder="Smith"
193	                    maxLength={256}
194	                    value={fields.lastName}
195	                    onChange={handleChange}
196	                    onBlur={handleBlur}
197	                    required
198	                    aria-required="true"
199	                    aria-invalid={!!errors.lastName}
200	                    aria-describedby={
201	                      errors.lastName ? "lastName-error" : undefined
202	                    }
203	                    className={styles.input}
204	                  />
205	                  {errors.lastName && (
206	                    <p
207	                      id="lastName-error"
208	                      className={styles.fieldError}
209	                      role="alert"
210	                    >
211	                      {errors.lastName}
212	                    </p>
213	                  )}
214	                </div>
215	              </div>
216	
217	              {/* Email + Phone */}
218	              <div className={styles.rowTwo}>
219	                <div className={styles.field}>
220	                  <div className={styles.labelRow}>
221	                    <label htmlFor="email" className={styles.label}>
222	                      Email
223	                    </label>
224	                    <span className={styles.required} aria-hidden="true">
225	                      *
226	                    </span>
227	                  </div>
228	                  <input
229	                    id="email"
230	                    name="email"
231	                    type="email"
232	                    placeholder="email@example.com"
233	                    maxLength={256}
234	                    value={fields.email}
235	                    onChange={handleChange}
236	                    onBlur={handleBlur}
237	                    required
238	                    aria-required="true"
239	                    aria-invalid={!!errors.email}
240	                    aria-describedby={
241	                      errors.email ? "email-error" : undefined
242	                    }
243	                    className={styles.input}
244	                  />
245	                  {errors.email && (
246	                    <p
247	                      id="email-error"
248	                      className={styles.fieldError}
249	                      role="alert"
250	                    >
251	                      {errors.email}
252	                    </p>
253	                  )}
254	                </div>
255	
256	                <div className={styles.field}>
257	                  <label htmlFor="phone" className={styles.label}>
258	                    Phone
259	                  </label>
260	                  <input
261	                    id="phone"
262	                    name="phone"
263	                    type="tel"
264	                    placeholder="+1 (123) 456 7890"
265	                    maxLength={256}
266	                    value={fields.phone}
267	                    onChange={handleChange}
268	                    onBlur={handleBlur}
269	                    className={styles.input}
270	                  />
271	                </div>
272	              </div>
273	
274	              {/* Inquiry Type */}
275	              <div className={styles.field}>
276	                <div className={styles.labelRow}>
277	                  <label htmlFor="inquiryType" className={styles.label}>
278	                    What Are You Looking For?
279	                  </label>
280	                  <span className={styles.required} aria-hidden="true">
281	                    *
282	                  </span>
283	                </div>
284	                <select
285	                  id="inquiryType"
286	                  name="inquiryType"
287	                  value={fields.inquiryType}
288	                  onChange={handleChange}
289	                  onBlur={handleBlur}
290	                  required
291	                  aria-required="true"
292	                  aria-invalid={!!errors.inquiryType}
293	                  aria-describedby={
294	                    errors.inquiryType ? "inquiryType-error" : undefined
295	                  }
296	                  className={styles.select}
297	                >
298	                  <option value="">Select an option...</option>
299	                  {INQUIRY_OPTIONS.map((opt) => (
300	                    <option key={opt.value} value={opt.value}>
301	                      {opt.label}
302	                    </option>
303	                  ))}
304	                </select>
305	                {errors.inquiryType && (
306	                  <p
307	                    id="inquiryType-error"
308	                    className={styles.fieldError}
309	                    role="alert"
310	                  >
311	                    {errors.inquiryType}
312	                  </p>
313	                )}
314	              </div>
315	
316	              {/* Message */}
317	              <div className={styles.field}>
318	                <label htmlFor="message" className={styles.label}>
319	                  Message
320	                </label>
321	                <textarea
322	                  id="message"
323	                  name="message"
324	                  placeholder="Enter your message..."
325	                  maxLength={5000}
326	                  value={fields.message}
327	                  onChange={handleChange}
328	                  onBlur={handleBlur}
329	                  className={styles.textarea}
330	                  aria-describedby="message-counter"
331	                />
332	                <p
333	                  id="message-counter"
334	                  className={styles.charCounter}
335	                  aria-live="polite"
336	                >
337	                  {(fields.message ?? "").length}/5000 characters
338	                </p>
339	              </div>
340	
341	              {/* Form-level error */}
342	              {status === "error" && (
343	                <p className={styles.errorMsg} role="alert">
344	                  Oops! Something went wrong while submitting the form. Please
345	                  try again or email us directly.
346	                </p>
347	              )}
348	
349	              <div>
350	                <button
351	                  type="submit"
352	                  className={styles.submitBtn}
353	                  disabled={status === "submitting"}
354	                >
355	                  {status === "submitting" ? "Please wait..." : "Send Message"}
356	                </button>
357	              </div>
358	            </form>
359	          </>
360	        )}
361	      </div>
362	    </section>
363	  );
364	}
