106	          </button>
107	        )}
108	      </div>
109	
110	      {/* Category header */}
111	      <div className={styles.categoryHeader}>
112	        <h3 className={styles.categoryTitle}>Service Categories</h3>
113	        {activeCategories.length > 0 && (
